        grid_z = N * Cout

        bias_arg = b if b is not None else u64(0)

        mod.launch(
            func_name,
            grid=(grid_x, grid_y, grid_z),
            block=(block_x, block_y, 1),
            arguments=[
                x,
                w,
                bias_arg,
                y,
                i32(N),
                i32(Cin),
                i32(H),
                i32(W),
                i32(Cout),
                i32(KH),
                i32(KW),
                i32(self.stride),
                i32(self.pad_h),
                i32(self.pad_w),
                i32(self.dil_h),
                i32(self.dil_w),
                i32(OH),
                i32(OW),
            ],
            shared_memory=0,
            stream=torch.cuda.current_stream(x.device),
        )
        return y
